[ExtensionOf(classStr(PurchAutoCreate_PurchReq))]
final class METPurchAutoCreatePurchReq_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// Updates the 3 fields to the new PO from PR
    /// </summary>
    protected void createLines()
    {
        PurchReqTable   metIntPurchreqTable;
        CustParameters  metCustParameters;

        next createLines();

        metIntPurchreqTable = PurchReqTable::findByPurchReqId(purchLine.purchReqId);
        metCustParameters  = CustParameters::find();

        if (metIntPurchreqTable.BusinessJustification == metCustParameters.METPRReason)
        {
            purchTable.selectForUpdate(true);
            purchTable.ReasonTableRef   = ReasonTableRef::createFromCode(metCustParameters.METPOReason);
            purchTable.METRDCustAccount = metIntPurchreqTable.METRDCustAccount;
            PurchTable.VendorRef = strfmt("%1 %2", metIntPurchreqTable.METRDCustAccount, CustTable::find(metIntPurchreqTable.METRDCustAccount).name());
            purchTable.update();
        }
    }
